INSERT INTO "CertificateTemplate" (id,name,kind,title,issuer,body,revision,"createdAt") VALUES (gen_random_uuid(),'Obediencia básica','TRAINING','Registro de obediencia básica','ORYX K9 · Unidad Canina','Ejercicios: atención al guía, sentado, tumbado, permanencia y llamada. Anota nivel de ayuda, tiempo de permanencia y respuesta en cada ejercicio.
INSERT INTO "CertificateTemplate" (id,name,kind,title,issuer,body,revision,"createdAt") VALUES (gen_random_uuid(),'Obediencia avanzada','TRAINING','Evaluación de obediencia avanzada','ORYX K9 · Unidad Canina','Evalúa distancia, duración, distractores y respuesta a señales. Registra criterios de logro y objetivos de la siguiente sesión.
INSERT INTO "CertificateTemplate" (id,name,kind,title,issuer,body,revision,"createdAt") VALUES (gen_random_uuid(),'Socialización','TRAINING','Seguimiento de socialización','ORYX K9 · Unidad Canina','Registra el entorno, estímulos, distancia de trabajo, respuesta del perro y apoyos utilizados. Describe avances y situaciones que requieren seguimiento.
INSERT INTO "CertificateTemplate" (id,name,kind,title,issuer,body,revision,"createdAt") VALUES (gen_random_uuid(),'Detección de drogas','TRAINING','Seguimiento de detección de drogas','ORYX K9 · Unidad Canina','Registra objetivo autorizado de la sesión, escenarios, búsquedas, aciertos, falsas alertas, omisiones y valoración del entrenador.
INSERT INTO "CertificateTemplate" (id,name,kind,title,issuer,body,revision,"createdAt") VALUES (gen_random_uuid(),'Búsqueda y rescate','TRAINING','Evaluación de búsqueda y rescate','ORYX K9 · Unidad Canina','Registra escenario, condiciones ambientales, duración, localizaciones, guía responsable y observaciones de seguridad.
INSERT INTO "CertificateTemplate" (id,name,kind,title,issuer,body,revision,"createdAt") VALUES (gen_random_uuid(),'Embajador canino','TRAINING','Formación de embajador canino','ORYX K9 · Unidad Canina','Registra convivencia, manejo en público, tolerancia a estímulos y participación en actividades educativas. Describe condiciones y apoyos para futuras presentaciones.
INSERT INTO "CertificateTemplate" (id,name,kind,title,issuer,body,revision,"createdAt") VALUES (gen_random_uuid(),'Registro de crianza y camada','BREEDING','Ficha de crianza y nacimiento','ORYX K9 · Unidad Canina','Registra progenitores, fecha del cruce, nacimiento previsto, nacimiento real, nacidos vivos, incidencias y fecha prevista de entrega.
INSERT INTO "CertificateTemplate" (id,name,kind,title,issuer,body,revision,"createdAt") VALUES (gen_random_uuid(),'Servicios médicos','MEDICAL','Registro de atención médica','ORYX K9 · Unidad Canina','Anota motivo de consulta, profesional responsable, hallazgos, indicaciones documentadas y próxima revisión. Adjunta los documentos emitidos por el profesional.
INSERT INTO "CertificateTemplate" (id,name,kind,title,issuer,body,revision,"createdAt") VALUES (gen_random_uuid(),'Charla educativa','TALK','Registro de charla y educación canina','ORYX K9 · Unidad Canina','Registra institución, tema, lugar, fecha, público, número de participantes, responsable y acuerdos de seguimiento.
INSERT INTO "CertificateTemplate" (id,name,kind,title,issuer,body,revision,"createdAt") VALUES (gen_random_uuid(),'Servicio municipal','MUNICIPAL','Parte de servicio municipal','ORYX K9 · Unidad Canina','Registra municipalidad, contrato o solicitud, equipo asignado, horario, actividad realizada, resultados e incidencias. Incluye la persona que recibe el servicio.
INSERT INTO "CertificateTemplate" (id,name,kind,title,issuer,body,revision,"createdAt") VALUES (gen_random_uuid(),'Servicio extraordinario','EXTRAORDINARY','Parte de servicio extraordinario','ORYX K9 · Unidad Canina','Registra solicitante, motivo, autorización, ubicación, personal y perros participantes, duración, recursos utilizados e incidencias.
INSERT INTO "CertificateTemplate" (id,name,kind,title,issuer,body,revision,"createdAt") VALUES (gen_random_uuid(),'Entrega y custodia','SERVICE','Acta de entrega y custodia','ORYX K9 · Unidad Canina','Registra propietario, custodio que entrega, custodio que recibe, identificación del perro, documentos, pertenencias, estado observado y compromisos de seguimiento.
INSERT INTO "CertificateTemplate" (id,name,kind,title,issuer,body,revision,"createdAt") VALUES (gen_random_uuid(),'Control de inventario','SERVICE','Registro de entrega de equipo','ORYX K9 · Unidad Canina','Registra artículo, lote o serie, cantidad, estado, responsable, destino, fecha de entrega y devolución prevista. Vincula el movimiento del inventario.
INSERT INTO "CertificateTemplate" (id,name,kind,title,issuer,body,revision,"createdAt") VALUES (gen_random_uuid(),'Acuerdo de servicio municipal','CONTRACT','Condiciones del servicio municipal','ORYX K9 · Unidad Canina','Describe alcance, horarios, responsabilidades, equipo asignado, vigencia, precio, forma de pago y condiciones de renovación acordadas.
INSERT INTO "CertificateTemplate" (id,name,kind,title,issuer,body,revision,"createdAt") VALUES (gen_random_uuid(),'Acuerdo de servicio extraordinario','CONTRACT','Condiciones del servicio extraordinario','ORYX K9 · Unidad Canina','Describe actividad autorizada, lugar, duración, personal, recursos, precio y condiciones de cancelación acordadas.
