
-- Independent commercial purposes preserve existing classifications.
ALTER TABLE "CertificateTemplate" DROP CONSTRAINT "CertificateTemplate_kind_check";
ALTER TABLE "CertificateTemplate" ADD CONSTRAINT "CertificateTemplate_kind_check" CHECK (kind IN ('TRAINING','BREEDING','CONTRACT','MEDICAL','TALK','MUNICIPAL','EXTRAORDINARY','SERVICE'));
ALTER TABLE "Dog" ADD COLUMN "availableForSale" BOOLEAN NOT NULL DEFAULT false,
 ADD COLUMN "availableForBreeding" BOOLEAN NOT NULL DEFAULT false;
UPDATE "Dog" SET "availableForSale" = ("commercialCategory" = 'FOR_SALE'),
 "availableForBreeding" = ("commercialCategory" = 'FOR_BREEDING');
ALTER TABLE "Dog" DROP CONSTRAINT "sale_publication_complete";
ALTER TABLE "Dog" ADD CONSTRAINT "sale_publication_complete" CHECK (
 NOT "salePublished" OR ("availableForSale" AND "salePrice" IS NOT NULL AND "salePrice">0 AND length(btrim(coalesce("saleContact",'')))>0)
);
-- Expression indexes cover existing data and concurrent writes, including archived records.
-- Stop on a conflict rather than changing an animal's identity without review.
CREATE UNIQUE INDEX "Dog_code_normalized_key" ON "Dog" (upper(btrim("code")));
CREATE UNIQUE INDEX "Dog_microchip_normalized_key" ON "Dog" (nullif(upper(regexp_replace("microchip", '[[:space:]-]', '', 'g')), ''));
CREATE UNIQUE INDEX "Dog_pedigreeNumber_normalized_key" ON "Dog" (nullif(upper(regexp_replace("pedigreeNumber", '[[:space:]-]', '', 'g')), ''));
ALTER TABLE "BreedingPlan" ADD COLUMN "expectedBirthDate" DATE, ADD COLUMN "expectedDeliveryDate" DATE;
-- Keep historic ranges; use their start as the initial expected date.
UPDATE "BreedingPlan" SET "expectedBirthDate" = "windowStart";
CREATE TABLE "Breed" (
 "id" UUID NOT NULL DEFAULT gen_random_uuid(), "name" TEXT NOT NULL, "group" TEXT,
 "standardNumber" INTEGER, "sourceUrl" TEXT, "notes" TEXT,
 "archivedAt" TIMESTAMPTZ(3), "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CONSTRAINT "Breed_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "Breed_name_key" ON "Breed" ("name");
CREATE UNIQUE INDEX "Breed_name_normalized_key" ON "Breed" (lower(btrim("name")));

